    {
      "name": "Differentiation Rules",
      "aliases": ["differentiation rules", "求导法则"],
      "definition_snippet": "Rules for computing derivatives, including power, constant multiple, sum, and difference rules.",
      "category": "concept"
    },
    {
      "name": "Derivative",
      "aliases": ["derivative", "导数"],
      "definition_snippet": "The derivative f'(x) represents the instantaneous rate of change of a function.",
      "category": "concept"
    },
    {
      "name": "Differentiation",
      "aliases": ["differentiation", "求导"],
      "definition_snippet": "The operation of finding a derivative.",
      "category": "operation"
    },
    {
      "name": "Power Rule",
      "aliases": ["power rule", "幂法则"],
      "definition_snippet": "If f(x)=x^n, then f'(x)=nx^{n-1}.",
      "category": "theorem"
    },
    {
      "name": "Real Exponent",
      "aliases": ["real exponent", "实数指数"],
      "definition_snippet": "The Power Rule applies when n is any real number.",
      "category": "concept"
    },
    {
      "name": "Constant Multiple Rule",
      "aliases": ["constant multiple rule", "常数倍法则"],
      "definition_snippet": "If c is constant and f is differentiable, then d/dx[cf(x)] = cf'(x).",
      "category": "theorem"
    },
    {
      "name": "Sum Rule",
      "aliases": ["sum rule", "和法则"],
      "definition_snippet": "If f and g are differentiable, then d/dx[f(x)+g(x)] = f'(x)+g'(x).",
      "category": "theorem"
    },
    {
      "name": "Difference Rule",
      "aliases": ["difference rule", "差法则"],
      "definition_snippet": "If f and g are differentiable, then d/dx[f(x)-g(x)] = f'(x)-g'(x).",
      "category": "theorem"
    },
    {
      "name": "Differentiable Function",
      "aliases": ["differentiable function", "可导函数"],
      "definition_snippet": "A function whose derivative exists.",
      "category": "property"
    },
    {
      "name": "Polynomial",
      "aliases": ["polynomial", "多项式"],
      "definition_snippet": "A function built from powers of x with constant coefficients.",
      "category": "concept"
    },
    {
      "name": "Exponential Function",
      "aliases": ["exponential function", "指数函数"],
      "definition_snippet": "A function of the form a^x.",
      "category": "concept"
    },
    {
      "name": "e^x",
      "aliases": ["natural exponential function", "自然指数函数"],
      "definition_snippet": "The exponential function with base e; its derivative is itself.",
      "category": "concept"
    },
    {
      "name": "a^x",
      "aliases": ["general exponential function", "一般指数函数"],
      "definition_snippet": "An exponential function with base a; d/dx(a^x)=a^x ln a.",
      "category": "concept"
    },
    {
      "name": "Number e",
      "aliases": ["Euler's number", "自然常数"],
      "definition_snippet": "The unique number satisfying lim_{h→0}(e^h-1)/h=1.",
      "category": "concept"
    },
    {
      "name": "Limit",
      "aliases": ["limit", "极限"],
      "definition_snippet": "A limiting process used to define e and derivatives.",
      "category": "concept"
    },
    {
      "name": "Natural Logarithm",
      "aliases": ["natural logarithm", "自然对数"],
      "definition_snippet": "The logarithm ln a appears in the derivative of a^x.",
      "category": "concept"
    },
    {
      "name": "Velocity",
      "aliases": ["velocity", "速度"],
      "definition_snippet": "The derivative of position: v(t)=s'(t).",
      "category": "concept"
    },
    {
      "name": "Position Function",
      "aliases": ["position function", "位置函数"],
      "definition_snippet": "A function s(t) describing position over time.",
      "category": "concept"
    },
    {
      "name": "Acceleration",
      "aliases": ["acceleration", "加速度"],
      "definition_snippet": "The derivative of velocity: a(t)=v'(t)=s''(t).",
      "category": "concept"
    },
    {
      "name": "Second Derivative",
      "aliases": ["second derivative", "二阶导数"],
      "definition_snippet": "The derivative of a derivative, written s''(t).",
      "category": "concept"
    },
    {
      "name": "Marginal Cost",
      "aliases": ["marginal cost", "边际成本"],
      "definition_snippet": "The derivative of the cost function: MC=C'(x).",
      "category": "concept"
    },
    {
      "name": "Cost Function",
      "aliases": ["cost function", "成本函数"],
      "definition_snippet": "A function C(x) representing total cost.",
      "category": "concept"
    },
    {
      "name": "Rate of Change",
      "aliases": ["rate of change", "变化率"],
      "definition_snippet": "The interpretation of the derivative as a rate.",
      "category": "concept"
    },
    {
      "name": "Tangent Line Approximation",
      "aliases": ["tangent line approximation", "切线近似"],
      "definition_snippet": "Uses the derivative to estimate function values near a known point.",
      "category": "operation"
    },
    {
      "name": "Integration",
      "aliases": ["antidifferentiation", "积分"],
