      "category": "operation"
    },
    {
      "name": "Fundamental Theorem of Calculus",
      "aliases": ["fundamental theorem of calculus", "微积分基本定理"],
      "definition_snippet": "Connects differentiation and integration.",
      "category": "theorem"
    }
  ],
